namespace emon;


public static class Hellotest {
    [Xunit.Fact]
    public static void TestGcdOfTwelveAndEighteenIsSix() {
        emon.Testport.AssertEq(Hello.Gcd(12, 18), 6, "gcd(12,18)");
        emon.Testport.AssertEq(Hello.Gcd(42, 63), 21, "gcd(42,63)");
    }
    [Xunit.Fact]
    public static void TestGcdWithZeroIsTheOther() {
        emon.Testport.AssertEq(Hello.Gcd(0, 9), 9, "gcd(0,9)");
        emon.Testport.AssertEq(Hello.Gcd(9, 0), 9, "gcd(9,0)");
    }
    [Xunit.Fact]
    public static void TestAHexBlobReadsBigEndian() {
        emon.Testport.AssertEq(emon.Port.BlobU16(emon.Testport.HexBlob("80 ff"), 0), 33023, "u16 of 80ff");
    }
    [Xunit.Fact]
    public static void TestARowLoopNamesItsRow() {
        int i = 0;
        while (i < 3) {
            emon.Testport.AssertEqAt(Hello.Gcd(i + 1, 1), 1, "gcd(n,1)", i);
            i += 1;
        }
    }
    [Xunit.Fact]
    public static void TestATextSinkComparesWithALiteral() {
        System.Text.StringBuilder t = emon.Testport.NewText();
        emon.Port.TextAscii(t, "n=");
        emon.Port.TextI32(t, 42);
        emon.Testport.AssertText(t, "n=42", "text");
        emon.Testport.AssertThat(1 < 2, "one is less than two");
    }
    [Xunit.Fact]
    public static void Test32BitShiftsLoseBitsOffTheTopAndKeepTheSign() {
        // Operands are LOCALS: Go folds a constant shift at compile time and
        // refuses `1 << 31` as an int32 overflow, where a variable wraps.
        int one = 1;
        int three = 3;
        int neg = -16;
        emon.Testport.AssertEq((one) << (4), 16, "1 << 4");
        emon.Testport.AssertEq((one) << (31), -2147483648, "1 << 31 is the sign bit");
        emon.Testport.AssertEq((three) << (30), -1073741824, "3 << 30 drops the top bit");
        emon.Testport.AssertEq((neg) >> (2), -4, "arithmetic right shift keeps the sign");
        emon.Testport.AssertEq((4096) >> (12), 1, "4096 >> 12");
    }
